1|// ★ D-2 — THE DECISION CONSULTS THE REGISTRY (the goal's D-2 layer-edge).
2|//
3|// THE DEFECT THIS CLOSES (measured 2026-09-23, the dist-content gate):
4|//   the deployed bundle carried ZERO kernel symbols —
5|//     dumbDetector=0 · theatricalDetector=0 · classifyByDetectors=0 · runKernelV2=0 ·
6|//     preflight=0 · FireGate=0 · FireLedger=0 · PolicyStore=0
7|//   — because the kernel was reached ONLY through TYPE-ONLY imports across the production
8|//   graph (`layer-registry.ts:22  import type { LayerId } from "./kernel-v2.ts"`), which the
9|//   bundler ERASES. The extension exposed the REGISTRY (consumptionAudit) but never the
10|//   DECISION — so the artifact that runs could not decide. This module is the value-wired
11|//   seam: the extension calls `decideFromRegistry`, so the bundler KEEPS the kernel, and the
12|//   kernel's layer declarations come FROM THE REGISTRY (never a raw store, never a file check).
13|//
14|// ★ THE LAYER-EDGE (the goal's contract): every one of the 6 graph layers is an INPUT to
15|//   THIS decision. A layer that is down refuses the stack with its NAMED code; a layer that
16|//   is up but silent contributes no certification. The verdict is the kernel's, and it cites
17|//   the registry's own evidence.
18|
19|import { buildRegistry, SIX_L2E_CONSUMERS } from "./layer-consumption.ts";
20|import type { ConsumerId, LayerFact } from "./layer-registry.ts";
21|import { runKernelV2, type KernelRun, type LayerDeclaration, type LayerId, type Verdict } from "./kernel-v2.ts";
22|import * as path from "node:path";
23|import * as fs from "node:fs";
24|import { graphFacts, type GraphFactInput, type GraphFactVerdict } from "./graph-facts.ts";
25|import type { DecisionRow } from "./fire-gate.ts";
26|import { FireLedger } from "./fire-ledger.ts";
27|import { PolicyStore, DEFAULT_POLICY_FILE } from "./policy-store.ts";
28|import { corbellCheckoutPath } from "./populate-corbell.ts";
29|
30|/** The 6 graph layers the kernel's PREFLIGHT asks. TSG + ABIDE are KERNELS, not layers —
31| *  they ride as certifications, never as preflight dependencies. */
32|const LAYER_IDS: readonly LayerId[] = [
33|  "L1_SEMANTICA",
34|  "L2_ARSUMBRIS",
35|  "L3_UA",
36|  "L4_C2KG",
37|  "L5_CORBELL",
38|  "L6_GRAPHIFY",
39|];
40|
41|/** The act under decision. Mirrors the kernel's DetectorContext fields it can know from here. */
42|export interface DecisionAct {
43|  toolName: string;
44|  target: string;
45|  /** Did this session query/read the target BEFORE the act? (the dumb signal) */
46|  queriedBefore: boolean;
47|  claims?: Array<{ text: string; spans: number }>;
48|}
49|
50|export interface DecisionEvidence {
51|  subject: string;
52|  scopeRoot: string;
53|  /** The layer consumers the registry supplied to the preflight. */
54|  layersWired: number;
55|  /** Every consumer the registry knows (the closed set of 8). */
56|  consumersTotal: number;
57|  /** The anchored facts the registry contributed about `subject` (the decision's inputs). */
58|  facts: LayerFact[];
59|  /** Which consumers contributed >=1 anchored fact. */
60|  influenced: ConsumerId[];
61|  /** ★ THE VERDICT — the kernel's, over the registry's declarations. */
62|  run: KernelRun;
63|}
64|
65|/** ★ THE DECISION. It consults the REGISTRY — never a raw store, never a file check.
66| *
67| *  Chain: registry (8 consumers) → the 6 layers become the kernel's LayerDeclaration[]
68| *  (their `up()`/`evidence` are the preflight's subject) → the registry's ANCHORED facts
69| *  become the certifications the detectors read → `runKernelV2` returns the verdict.
70| *
71| *  A layer DOWN → `GI_STACK_INCOMPLETE:<id>` (the kernel's own refusal). A wired-but-silent
72| *  layer → NO certification from it (it never inflates the decision). NEVER an empty pass. */
73|export function decideFromRegistry(
74|  scopeRoot: string,
75|  subject: string,
76|  act: DecisionAct,
77|  record?: (run: KernelRun) => void,
78|): DecisionEvidence {
79|  const registry = buildRegistry(scopeRoot);
80|
81|  // The registry's facts for this subject — the decision's evidence base. `factsFor`
82|  // already filters to ANCHORED facts (an empty `source` is discarded by the registry).
83|  const facts = registry.factsFor(subject);
84|  const influenced = [...new Set(facts.map((f) => f.consumer))];
85|
86|  // ★ THE LAYER-EDGE: the kernel's layer declarations come FROM THE REGISTRY.
87|  //   `consumer.up()` is asked at decision time — the decision reads reality, not a cache.
88|  const layers: LayerDeclaration[] = registry
89|    .consumers()
90|    .filter((c) => (LAYER_IDS as readonly string[]).includes(c.id))
91|    .map((c) => ({
92|      id: c.id as LayerId,
93|      dependency: c.dependency,
94|      errorCode: c.errorCode,
95|      probe: () => {
96|        const s = c.up();
97|        return { up: s.up, evidence: s.evidence };
98|      },
99|    }));
100|
101|  // The registry's anchored facts become the certifications the detectors weigh.
102|  const certifications = facts.map((f) => ({
103|    layer: f.consumer as LayerId,
104|    verdict: "PASS" as Verdict,
105|    reason: `${f.source}`,
106|  }));
107|
108|  const run = runKernelV2({
109|    toolName: act.toolName,
110|    target: act.target,
111|    queriedBefore: act.queriedBefore,
112|    claims: act.claims ?? [],
113|    certifications,
114|    layers,
115|    record,
116|  });
117|
118|  return {
119|    subject,
120|    scopeRoot,
121|    layersWired: layers.length,
122|    consumersTotal: SIX_L2E_CONSUMERS.length,
123|    facts,
124|    influenced,
125|    run,
126|  };
127|}
128|
129|/** ★ THE L5/L6 WIRE — "the decision reads the parse-grade graph" (the DPL1's layer table).
130| *  The FireGate's ladder is graph → MPSE → cache → Jev: the graph answers FACTS and a fact
131| *  is never worth a model call. This is that rung, composed so the extension carries it. */
132|export interface FireEvidence {
133|  storePath: string;
134|  target: string;
135|  intent: GraphFactInput["intent"];
136|  verdicts: GraphFactVerdict[];
137|  /** True when the graph settled the fire — no model call was needed. */
138|  settles: boolean;
139|  /** The verdicts that demanded a FIRE (a real violation the graph found). */
140|  fires: number;
141|  policyCount: number;
142|  policySource: string;
143|  ledgerPath: string;
144|  /** ★ THE RECORD — a live FireLedger. The caller appends; nothing here fabricates a row. */
145|  ledger: FireLedger;
146|}
147|
148|/** ★ THE DECISION READS THE PARSE-GRADE GRAPH (L5 CORBELL, and L6 via the same store).
149| *  `graphFacts` is handed the TYPED STORE — absent ⇒ it says so (never a silent pass).
150| *  The policy comes from the PolicyStore (the seed policy set is the NAMED fallback);
151| *  the record is a FireLedger on disk (an in-memory ledger throws — it is not a ledger). */
152|export function decideFireFromGraph(
153|  scopeRoot: string,
154|  target: string,
155|  intent: GraphFactInput["intent"],
156|): FireEvidence {
157|  const storePath = corbellCheckoutPath(scopeRoot);
158|  const verdicts = graphFacts({ storePath, target, intent });
159|  const settles = verdicts.some((v) => v.settles);
160|  const fires = verdicts.filter((v) => v.action === "FIRE").length;
161|
162|  const policyPath = path.join(scopeRoot, ".omp", "graph-intelligence", "policy.json");
163|  let policyCount = Object.keys(DEFAULT_POLICY_FILE.policies).length;
164|  let policySource = "the seed policy set (no policy.json on disk — the named fallback)";
165|  try {
166|    const store = new PolicyStore(policyPath);
167|    policyCount = Object.keys(store.all()).length;
168|    policySource = policyPath;
169|  } catch {
170|    // the seed set stands; `policySource` NAMES that, so the count is never anonymous
171|  }
172|
173|  const ledgerPath = path.join(scopeRoot, ".omp", "graph-intelligence", "fire-decisions.db");
174|  // ★ THE FRESH-SCOPE FIX (2026-09-23, found in the omp-ct TUI): `gi-decide` with a
175|  //   scopeRoot that had never hosted the kernel FAILED with
176|  //   `GI_LEDGER_OPEN_FAILED: cannot open or migrate the fire ledger at
177|  //    /tmp/.omp/graph-intelligence/fire-decisions.db (unable to open database file)`
178|  //   — the ledger's DIRECTORY did not exist and FireLedger opens the path directly.
179|  //   A decision must never fail because its RECORD had nowhere to live: create the dir.
180|  fs.mkdirSync(path.dirname(ledgerPath), { recursive: true });
181|  const ledger = new FireLedger(ledgerPath);
182|
183|  return { storePath, target, intent, verdicts, settles, fires, policyCount, policySource, ledgerPath, ledger };
184|}
